                    "5\tFlottant\tDescend lentement lorsqu'il est lâché.",
                    "6\tChatoyant\tScintille et brille d'une lumière vive comme une torche.",
                    "7\tInvisible\tL'objet est invisible, mais devient visible pendant 1 round après avoir été utilisé.",
