/**
 * Rank words of the skill feat prerequisites, mapped to rank letters.
 */
DON.FEAT_RANKS = {
    "qualifié": "Q",
    "expert"  : "E",
    "maître"  : "M",
    "légende" : "L"
};

/**
 * Tells whether one required string of a skill feat holds: "<rank> en
 * <skill> ou en <skill>", the trailing extras after a comma are not skill
 * requirements. Returns true/false, null when the string carries no skill
 * requirement (permissive).
 *
 * @param {string} required_string  Ex: "qualifié en Athlétisme ou en Nature"
 * @param {Object} rank_by_label    Skill label -> current rank letter
 * @returns {boolean|null}          The requirement outcome, null when not a skill requirement
 */
DON.isSkillRequirementMet = function ( required_string, rank_by_label ) {
    let rank_match = required_string.match( /^(qualifié|expert|maître|légende)\s+en\s+(.+)$/i );
    if ( !rank_match ) {
        return null;
    }
    let required_rank = DON.FEAT_RANKS[ rank_match[ 1 ].toLowerCase() ];
    let skill_names   = rank_match[ 2 ].split( /\s+ou\s+(?:en\s+)?/i );
    for ( let i = 0, _size_i = skill_names.length; i < _size_i; i++ ) {
        let skill_label = skill_names[ i ].split( "," )[ 0 ].trim();
        let current_rank = rank_by_label[ skill_label ];
        if ( current_rank && MASTERY.ORDER[ current_rank ] >= MASTERY.ORDER[ required_rank ] ) {
            return true;
        }
    }
    return false;
};

/**
 * A skill feat is available when every skill requirement of its
 * prerequisites holds (the non-skill ones are permissive).
 *
 * @param {Object} feat            A DON.SKILL entry
 * @param {Object} rank_by_label    Skill label -> current rank letter
 * @returns {boolean}              True when the character may take the feat
 */
DON.isSkillFeatAvailable = function ( feat, rank_by_label ) {
    if ( !feat.required || !feat.required.length ) {
        return true;
    }
    for ( let i = 0, _size_i = feat.required.length; i < _size_i; i++ ) {
        if ( DON.isSkillRequirementMet( feat.required[ i ], rank_by_label ) === false ) {
            return false;
        }
    }
    return true;
};

/**
 * Skill feats open to the character: level low enough and prerequisites held.
 *
 * @param {Object} rank_by_label  Skill label -> current rank letter
 * @param {number} max_level      Level of the line choosing the feat
 * @returns {Array}               [ { name } ] of the available feats
 */
DON.getAvailableSkillFeats = function ( rank_by_label, max_level ) {
    let to_return = [];
    let feats     = DON.SKILL.ENUM[ 0 ];
    for ( let i = 0, _size_i = feats.length; i < _size_i; i++ ) {
        if ( parseInt( feats[ i ].level, 10 ) > max_level ) {
            continue;
        }
        if ( !DON.isSkillFeatAvailable( feats[ i ], rank_by_label ) ) {
            continue;
        }
        to_return.push( { "name": feats[ i ].name } );
    }
    return to_return;
};

/**
 * General feats open to the character: level low enough and prerequisites
 * held (the same rule as the skill feats: a skill prerequisite is checked
 * against the ranks, anything else is permissive).
 *
 * @param {Object} rank_by_label  Skill label -> current rank letter
 * @param {number} max_level      Level of the line choosing the feat
 * @returns {Array}               [ { name } ] of the available feats
 */
DON.getAvailableGeneralFeats = function ( rank_by_label, max_level ) {
    let to_return = [];
    let feats     = DON.GENERAL.ENUM;
    for ( let i = 0, _size_i = feats.length; i < _size_i; i++ ) {
        if ( parseInt( feats[ i ].level, 10 ) > max_level ) {
            continue;
        }
        if ( !DON.isSkillFeatAvailable( feats[ i ], rank_by_label ) ) {
            continue;
        }
        to_return.push( { "name": feats[ i ].name } );
    }
    return to_return;
};

/**
 * The raw scraped entry of a feat, by name and category.
 *
 * @param {string} feat_category  "general" | "skill" | "class" | "race"
 * @param {string} feat_name      Display name of the feat
 * @returns {Object|null}        The entry { name, level, traits, ... }, or null
 */
DON.getFeatEntry = function ( feat_category, feat_name ) {
    let feats = null;
    if ( feat_category === "general" ) {
        feats = DON.GENERAL.ENUM;
    }
    else if ( feat_category === "skill" ) {
        feats = DON.SKILL.ENUM[ 0 ];
    }
    else if ( feat_category === "class" ) {
        feats = DON.CLASS.ENUM;
    }
    else if ( feat_category === "race" ) {
        feats = DON.RACE.ENUM[ 0 ];
    }
    if ( !feats ) {
        return null;
    }
    for ( let i = 0, _size_i = feats.length; i < _size_i; i++ ) {
        if ( feats[ i ].name === feat_name ) {
            return feats[ i ];
        }
    }
    return null;
};

/**
 * Popup data of a feat, by name. The feat category matches the line type:
 * "general" for the general feats, "skill" for the skill feats, "class"
 * for the class feats.
 *
 * @param {string} feat_category  "general" | "skill" | "class" | "race"
 * @param {string} feat_name       Display name of the feat
 * @returns {Object|null}         Popup-shaped object, or null when unknown
 */
DON.getFeatInformation = function ( feat_category, feat_name ) {
    let feat = DON.getFeatEntry( feat_category, feat_name );
    if ( !feat ) {
        return null;
    }
    return {
        "id"          : "feat__" + feat_category + "__" + feat_name,
        "category"    : "feat",
        "text"        : feat.name,
        "element_type": "Niveau " + feat.level,
        "required"    : feat.required,
        "traits"      : feat.traits,
        "description" : feat.description ? feat.description.join( "<br>" ) : ""
    };
};

/**
 * Every known feat of the scraped data: the skill, class and ancestry feat
 * lists, deduplicated by name and sorted.
 *
 * @returns {Array}  [ { name } ] of the feat names
 */
DON.getKnownFeats = function () {
    let to_return = [];
    let seen      = {};
    let feat_lists = [ DON.RACE.ENUM[ 0 ], DON.SKILL.ENUM[ 0 ], DON.CLASS.ENUM, DON.GENERAL.ENUM ];
    for ( let i = 0, _size_i = feat_lists.length; i < _size_i; i++ ) {
        for ( let f = 0, _size_f = feat_lists[ i ].length; f < _size_f; f++ ) {
            let feat_name = feat_lists[ i ][ f ].name;
            if ( seen[ feat_name ] ) {
                continue;
            }
            seen[ feat_name ] = true;
            to_return.push( { "name": feat_name } );
        }
    }
    to_return.sort( function ( feat_a, feat_b ) {
        return feat_a.name.localeCompare( feat_b.name, "fr" );
    } );
    return to_return;
};

/**
 * The category of a feat by its NAME (the adjustments selector lists the
 * union of every category, the "?" of an option needs the category to open
 * the feat popup).
 *
 * @param {string} feat_name  Display name of the feat
 * @returns {string|null}    "general" | "skill" | "class" | "race", or null
 */
DON.getFeatCategoryByName = function ( feat_name ) {
    let feat_lists = [
        [ "general", DON.GENERAL.ENUM ],
        [ "skill", DON.SKILL.ENUM[ 0 ] ],
        [ "class", DON.CLASS.ENUM ],
        [ "race", DON.RACE.ENUM[ 0 ] ]
    ];
    for ( let i = 0, _size_i = feat_lists.length; i < _size_i; i++ ) {
        let feats = feat_lists[ i ][ 1 ];
        for ( let f = 0, _size_f = feats.length; f < _size_f; f++ ) {
            if ( feats[ f ].name === feat_name ) {
                return feat_lists[ i ][ 0 ];
            }
        }
    }
    return null;
};
